import type { IcpDraft } from "../../_lib/icp-form";
import { BudgetUsagePlaceholder } from "./BudgetUsagePlaceholder";
import { EvidencePlaceholder } from "./EvidencePlaceholder";
import { IcpSummary } from "./IcpSummary";
import { OutreachDraftsPlaceholder } from "./OutreachDraftsPlaceholder";
import { Panel } from "./Panel";
import { ProspectScoresPlaceholder } from "./ProspectScoresPlaceholder";
import { StatTile } from "./StatTile";

type ResultsPanelProps = {
  icp: IcpDraft | null;
  pending: boolean;
};

function RunStatus({ icp, pending }: ResultsPanelProps) {
  if (pending) {
    return <>Checking your profile…</>;
  }
  if (icp) {
    return (
      <>
        Profile accepted. The prospecting pipeline is not connected yet, so no
        results are generated.
      </>
    );
  }
  return <>Define your ideal customer profile to start a run.</>;
}

export function ResultsPanel({ icp, pending }: ResultsPanelProps) {
  return (
    // A container, so the grids below respond to the results column's width
    // rather than the viewport's (the column is narrower beside the form).
    <section aria-labelledby="results-title" className="@container flex min-w-0 flex-col gap-5">
      <div className="flex flex-col gap-1">
        <h2
          id="results-title"
          className="text-lg font-semibold text-slate-900 dark:text-slate-100"
        >
          Results
        </h2>
        <p aria-live="polite" className="text-sm text-slate-600 dark:text-slate-300">
          <RunStatus icp={icp} pending={pending} />
        </p>
      </div>

      <div className="grid grid-cols-2 gap-3 @2xl:grid-cols-4">
        <StatTile label="Companies found" value="—" />
        <StatTile label="Qualified" value="—" />
        <StatTile label="Average fit" value="—" />
        <StatTile label="Drafts ready" value="—" />
      </div>

      {icp && (
        <Panel title="Active profile" description="The profile the next run will use.">
          <IcpSummary icp={icp} />
        </Panel>
      )}

      <ProspectScoresPlaceholder pending={pending} />

      <div className="grid gap-5 md:grid-cols-2">
        <EvidencePlaceholder />
        <BudgetUsagePlaceholder />
      </div>

      <OutreachDraftsPlaceholder />
    </section>
  );
}

import type { ReactNode } from "react";

type PanelProps = {
  title: string;
  description?: string;
  badge?: ReactNode;
  className?: string;
  children: ReactNode;
};

export function Panel({ title, description, badge, className, children }: PanelProps) {
  const headingId = `panel-${title.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`;
  return (
    <section
      aria-labelledby={headingId}
      className={`flex flex-col gap-4 rounded-2xl border border-slate-200 bg-white p-5 shadow-sm dark:border-slate-800 dark:bg-slate-900/60 ${className ?? ""}`}
    >
      <header className="flex flex-wrap items-start justify-between gap-2">
        <div className="flex min-w-0 flex-col gap-0.5">
          <h3
            id={headingId}
            className="text-sm font-semibold text-slate-900 dark:text-slate-100"
          >
            {title}
          </h3>
          {description && (
            <p className="text-xs text-slate-600 dark:text-slate-300">{description}</p>
          )}
        </div>
        {badge}
      </header>
      {children}
    </section>
  );
}

export function PlaceholderBadge({ children = "Awaiting run" }: { children?: ReactNode }) {
  return (
    <span className="shrink-0 rounded-full bg-slate-100 px-2 py-0.5 text-xs font-medium text-slate-600 dark:bg-slate-800 dark:text-slate-300">
      {children}
    </span>
  );
}

export function EmptyState({ children }: { children: ReactNode }) {
  return (
    <p className="rounded-lg border border-dashed border-slate-300 px-4 py-6 text-center text-sm text-slate-600 dark:border-slate-700 dark:text-slate-300">
      {children}
    </p>
  );
}

export function SkeletonBar({ className, animated }: { className?: string; animated?: boolean }) {
  return (
    <span
      aria-hidden="true"
      className={`block h-2.5 rounded-full bg-slate-200 dark:bg-slate-800 ${animated ? "animate-pulse" : ""} ${className ?? ""}`}
    />
  );
}

import type { ReactNode } from "react";

type FormFieldProps = {
  id: string;
  label: string;
  hint?: string;
  error?: string;
  optional?: boolean;
  children: ReactNode;
};

export function fieldDescriptionIds(id: string, hint?: string, error?: string) {
  const ids = [hint && `${id}-hint`, error && `${id}-error`].filter(Boolean);
  return ids.length > 0 ? ids.join(" ") : undefined;
}

export function inputClassName(hasError: boolean) {
  return [
    "block w-full rounded-lg border bg-white px-3 py-2 text-sm text-slate-900 shadow-xs",
    "placeholder:text-slate-500 focus:outline-none focus:ring-2 focus:ring-offset-0",
    "dark:bg-slate-900 dark:text-slate-100 dark:placeholder:text-slate-400",
    hasError
      ? "border-red-400 focus:border-red-500 focus:ring-red-500/30 dark:border-red-500/70"
      : "border-slate-300 focus:border-indigo-500 focus:ring-indigo-500/30 dark:border-slate-700",
  ].join(" ");
}

export function FormField({
  id,
  label,
  hint,
  error,
  optional,
  children,
}: FormFieldProps) {
  return (
    <div className="flex flex-col gap-1.5">
      <label
        htmlFor={id}
        className="flex items-baseline justify-between gap-2 text-sm font-medium text-slate-800 dark:text-slate-200"
      >
        {label}
        {optional && (
          <span className="text-xs font-normal text-slate-600 dark:text-slate-300">
            Optional
          </span>
        )}
      </label>
      {children}
      {hint && !error && (
        <p id={`${id}-hint`} className="text-xs text-slate-600 dark:text-slate-300">
          {hint}
        </p>
      )}
      {error && (
        <p id={`${id}-error`} className="text-xs font-medium text-red-600 dark:text-red-400">
          {error}
        </p>
      )}
    </div>
  );
}

import { Panel, PlaceholderBadge } from "./Panel";

const METERS = ["Searches", "Enrichments", "Credits"];

export function BudgetUsagePlaceholder() {
  return (
    <Panel
      title="Budget usage"
      description="Crustdata usage for this run, against limits set on the server."
      badge={<PlaceholderBadge>Synthetic</PlaceholderBadge>}
    >
      <ul className="flex flex-col gap-3">
        {METERS.map((meter) => (
          <li key={meter} className="flex flex-col gap-1.5">
            <div className="flex items-baseline justify-between text-xs">
              <span className="font-medium text-slate-700 dark:text-slate-300">{meter}</span>
              <span className="tabular-nums text-slate-600 dark:text-slate-300">0 used</span>
            </div>
            <div
              role="meter"
              aria-label={`${meter} used`}
              aria-valuemin={0}
              aria-valuemax={100}
              aria-valuenow={0}
              className="h-1.5 rounded-full bg-slate-200 dark:bg-slate-800"
            />
          </li>
        ))}
      </ul>
      <p className="text-xs text-slate-600 dark:text-slate-300">
        Synthetic mode never calls Crustdata, so no credits are spent.
      </p>
    </Panel>
  );
}

